/**
 * The map (build prompt, part 1): a description of the setup, generated by code from the running app
 * at the start of every build and after every update. Nobody keeps it by hand. It joins what the app
 * says (its loaded rows, settings, tools, modes) with what each add-on's own files say (lib/scan.js).
 * The map keeps the one before it, so it can show what changed.
 */
import { mask } from './text.js';

/** Instruction text one plugin may add to a mode before the fit check asks the user (a small model pays for every line). */
export const PLUGIN_TEXT_BUDGET = 1500;
/** The whole of a mode's own method (the Modes add-on's limit). */
export const MODE_TEXT_BUDGET = 4000;

/**
 * Who made a plugin.
 * @param {string} name - its package name.
 * @param {boolean} plus - whether it is one of the Plus add-ons (found in the Plus folder).
 * @param {object} [passport] - its passport's origin record, when it has one.
 * @returns {'built-in' | 'owner+claude' | 'creator-plus' | 'third-party'} the origin.
 */
export function originOf(name, plus, passport) {
  if (passport?.origin === 'creator-plus') return 'creator-plus';
  if (/^@deepseek-ai\//.test(name)) return 'built-in';
  if (plus) return 'owner+claude';
  return 'third-party';
}

/** @returns {boolean} whether Creator Plus may ever change a plugin of this origin (fixed rule 4). */
export const editable = (origin) => origin === 'owner+claude' || origin === 'creator-plus';

/** The id a loaded row is known by. */
const rowId = (entry) => String(entry?.options?.id ?? entry?.id ?? '');

/**
 * Build the map.
 * @param {object} input - what the app and the add-on folders say.
 * @param {object[]} input.entries - the app's loaded rows (`[...loader.entries()]`).
 * @param {object[]} input.settings - the settings service's `describe()` rows (`{ns, value}`).
 * @param {string[]} input.tools - the names of every tool the app knows.
 * @param {object[]} input.scans - lib/scan.js for each Plus add-on (and Creator Plus's own builds).
 * @param {Record<string, object>} [input.passports] - origin records by package name.
 * @param {string} input.appVersion - the app's version.
 * @param {string} [input.plusVersion] - Plus's version.
 * @param {number} [input.at] - when.
 * @returns {object} the map.
 */
export function buildMap({ entries = [], settings = [], tools = [], scans = [], passports = {}, appVersion = '', plusVersion = '', at = Date.now() }) {
  const byName = new Map(scans.map((scan) => [scan.name, scan]));
  const plugins = [];
  const seen = new Set();
  for (const entry of entries) {
    const name = String(entry?.options?.name ?? '');
    if (!name) continue;
    const scan = byName.get(name);
    const origin = originOf(name, Boolean(scan), passports[name]);
    plugins.push({
      id: rowId(entry),
      name,
      origin,
      locked: !editable(origin),
      enabled: entry?.disabled !== true,
      running: Boolean(entry?.fiber),
      version: scan?.version ?? '',
      folder: scan?.folder ?? '',
      touches: scan ? touchesOf(scan) : undefined,
    });
    seen.add(name);
  }
  // Plus add-ons in the folder that the app has not loaded (switched off by the owner, or not registered).
  for (const scan of scans) {
    if (seen.has(scan.name)) continue;
    const origin = originOf(scan.name, true, passports[scan.name]);
    plugins.push({ id: scan.rows[0] ?? scan.folder, name: scan.name, origin, locked: !editable(origin), enabled: false, running: false, version: scan.version, folder: scan.folder, touches: touchesOf(scan), notLoaded: true });
  }
  plugins.sort((a, b) => a.name.localeCompare(b.name));
  const modesRow = settings.find((row) => row?.ns === 'modes')?.value ?? {};
  const modes = modesOf(modesRow);
  const index = indexOf(plugins);
  const look = {};
  for (const scan of scans) for (const [name, count] of Object.entries(scan.cssVars ?? {})) look[name] = (look[name] ?? 0) + count;
  return {
    at,
    app: { version: String(appVersion ?? '') },
    plus: { version: String(plusVersion ?? '') },
    plugins,
    modes,
    tools: [...new Set(tools.map(String))].sort(),
    settings: settings.map((row) => ({ ns: String(row?.ns ?? ''), fields: row?.value && typeof row.value === 'object' ? Object.keys(row.value).sort().slice(0, 80) : [] })).filter((row) => row.ns),
    index,
    // The look of the harness as values: the app's colour, type and spacing variables the pages use, most used first.
    look: Object.entries(look).sort((a, b) => b[1] - a[1]).slice(0, 60).map(([name, uses]) => ({ name, uses })),
  };
}

/** What a scan says a plugin touches, in the map's words. */
export function touchesOf(scan) {
  return {
    provides: scan.provides, uses: scan.uses, events: scan.events, tools: scan.tools, commands: scan.commands,
    routes: scan.routes, slots: scan.slots, settings: scan.settingsNs, sections: scan.sections, modes: scan.modes,
    storage: scan.storage, config: scan.config, instructionChars: scan.methodChars, rows: scan.rows,
  };
}

/** The tabs, from the Modes add-on's settings: built-in and extra, with their tools and method length. */
export function modesOf(value) {
  const parse = (text) => {
    try {
      const parsed = typeof text === 'string' ? JSON.parse(text || '{}') : text;
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
    } catch {
      return {};
    }
  };
  const table = { ...parse(value.modes), ...parse(value.extraModes) };
  return Object.entries(table).map(([id, mode]) => ({
    id,
    label: String(mode?.label ?? id),
    isolated: mode?.isolated === true,
    tools: Array.isArray(mode?.tools) ? mode.tools.length : String(mode?.tools ?? 'all'),
    promptChars: String(mode?.prompt ?? '').length,
  })).sort((a, b) => a.id.localeCompare(b.id));
}

/** Who uses each name: the fit check's look-up. */
export function indexOf(plugins) {
  const index = { commands: {}, tools: {}, routes: {}, slots: {}, services: {}, settings: {}, storage: {}, sections: {}, modes: {}, rows: {} };
  const add = (kind, key, who) => {
    if (!key) return;
    (index[kind][key] ??= []).includes(who) || index[kind][key].push(who);
  };
  for (const plugin of plugins) {
    // Every loaded row, built-in ones too: a new plugin's row may not take the id of any of them.
    add('rows', plugin.id, plugin.name);
    const t = plugin.touches;
    if (!t) continue;
    for (const name of t.commands ?? []) add('commands', name, plugin.name);
    for (const name of t.tools ?? []) add('tools', name, plugin.name);
    for (const name of t.routes ?? []) add('routes', name, plugin.name);
    for (const slot of t.slots ?? []) add('slots', `${slot.name}#${slot.id}`, plugin.name);
    for (const name of t.provides ?? []) add('services', name, plugin.name);
    for (const name of t.settings ?? []) add('settings', name, plugin.name);
    for (const name of t.storage ?? []) add('storage', name, plugin.name);
    for (const name of t.sections ?? []) add('sections', name, plugin.name);
    for (const name of t.modes ?? []) add('modes', name, plugin.name);
    for (const name of t.rows ?? []) add('rows', name, plugin.name);
  }
  return index;
}

/**
 * What changed between two maps (after an update of the app or a plugin).
 * @returns {{app: string, added: string[], removed: string[], versions: string[], switched: string[], tools: {added: string[], removed: string[]}}} the changes, in plain words.
 */
export function diffMap(before, after) {
  const old = new Map((before?.plugins ?? []).map((plugin) => [plugin.name, plugin]));
  const now = new Map((after?.plugins ?? []).map((plugin) => [plugin.name, plugin]));
  const versions = [];
  const switched = [];
  for (const [name, plugin] of now) {
    const was = old.get(name);
    if (!was) continue;
    if (was.version !== plugin.version) versions.push(`${name}: ${was.version || '?'} → ${plugin.version || '?'}`);
    if (was.enabled !== plugin.enabled) switched.push(`${name}: ${plugin.enabled ? 'switched on' : 'switched off'}`);
  }
  const oldTools = new Set(before?.tools ?? []);
  const newTools = new Set(after?.tools ?? []);
  return {
    app: before?.app?.version !== after?.app?.version ? `${before?.app?.version || '?'} → ${after?.app?.version || '?'}` : '',
    added: [...now.keys()].filter((name) => !old.has(name)),
    removed: [...old.keys()].filter((name) => !now.has(name)),
    versions,
    switched,
    tools: { added: [...newTools].filter((name) => !oldTools.has(name)), removed: [...oldTools].filter((name) => !newTools.has(name)) },
  };
}

/** @returns {boolean} whether a map difference has anything in it. */
export const changed = (diff) => Boolean(diff.app || diff.added.length || diff.removed.length || diff.versions.length || diff.switched.length || diff.tools.added.length || diff.tools.removed.length);

/**
 * The part of the map a step needs, as text for a model: the selected plugins in full, the rest as
 * one line each (the fit check needs the whole map, a model rarely does). Masked.
 * @param {object} map - the map.
 * @param {string[]} [selected] - package names or ids shown in full.
 * @returns {string} the text.
 */
export function mapText(map, selected = []) {
  const want = new Set(selected);
  const lines = [`App ${map.app.version || '?'}, Plus ${map.plus.version || '?'}; ${map.plugins.length} plugins, ${map.modes.length} tabs, ${map.tools.length} tools.`];
  lines.push(`Tabs: ${map.modes.map((mode) => `${mode.id}${mode.isolated ? ' (sealed)' : ''}`).join(', ')}.`);
  for (const plugin of map.plugins) {
    const head = `- ${plugin.name} (${plugin.id}; ${plugin.origin}${plugin.locked ? ', locked' : ''}; ${plugin.enabled ? 'on' : 'off'}${plugin.version ? `; ${plugin.version}` : ''})`;
    if (!want.has(plugin.name) && !want.has(plugin.id) || !plugin.touches) {
      lines.push(head);
      continue;
    }
    const t = plugin.touches;
    const part = (label, list) => (list?.length ? `  ${label}: ${list.map((item) => (typeof item === 'string' ? item : `${item.name}#${item.id}`)).join(', ')}` : '');
    lines.push(head, ...[part('tools', t.tools), part('commands', t.commands), part('routes', t.routes), part('chat-box and page places', t.slots), part('services it provides', t.provides), part('services it uses', t.uses), part('events', t.events), part('settings', t.settings), part('config', t.config), part('storage', t.storage), part('instruction sections', t.sections), t.instructionChars ? `  method: ${t.instructionChars} characters` : ''].filter(Boolean));
  }
  return mask(lines.join('\n'));
}
